cd /work/packages/inngest/src; python3 - <<'E'
p='components/Inngest.ts'
s=open(p).read()
s=s.replace('''export const internalLoggerSymbol = Symbol.for("inngest.internalLogger");
''','''export const internalLoggerSymbol = Symbol.for("inngest.internalLogger");

/**
 * Symbol for accessing whether session propagation is enabled. Not part of
 * the public API.
 * @internal
 */
export const sessionPropagationSymbol = Symbol.for(
  "inngest.sessionPropagation",
);
''',1)
s=s.replace('''  /**
   * Given a response from Inngest, relay the error to the caller.''','''  /**
   * Whether session propagation is enabled. Resolved lazily from the current
   * env on every access, so env vars set after construction are honoured.
   *
   * @internal
   */
  get [sessionPropagationSymbol](): boolean {
    return (
      parseAsBoolean(this._env[envKeys.InngestSessionPropagation]) ?? false
    );
  }

  /**
   * Given a response from Inngest, relay the error to the caller.''',1)
open(p,'w').write(s)
p='helpers/consts.ts'
s=open(p).read()
s=s.replace('''  InngestDevMode = "INNGEST_DEV",
''','''  InngestDevMode = "INNGEST_DEV",

  /**
   * Enables session propagation (internal, off by default).
   */
  InngestSessionPropagation = "INNGEST_SESSION_PROPAGATION",
''',1)
open(p,'w').write(s)
E
git diff --stat; cd ..; npx tsc --noEmit -p . 2>&1 | head

